/**
 * Where uploaded files live. Same three functions whichever backend is configured:
 *   STORAGE_DRIVER=local -> files on disk under STORAGE_DIR (development)
 *   STORAGE_DRIVER=s3    -> Vultr Object Storage via its S3-compatible API (production). Bucket stays private.
 * Keys look like "<patientId>/<entryId>.webp" and are always generated by the API, never by the user.
 */
import fs from 'node:fs/promises';
import path from 'node:path';
import { DeleteObjectCommand, GetObjectCommand, PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { config } from '../config';
import { AppError } from '../middleware/errors';

export interface FileRef {
  storage: 'local' | 's3';
  key: string;
}

// ---------- local disk ----------
const root = path.resolve(config.STORAGE_DIR);

function localPath(key: string): string {
  const full = path.resolve(root, key);
  if (!full.startsWith(root + path.sep)) throw new AppError(400, 'INVALID_FILE_KEY', 'Invalid file key'); // no ../ escapes
  return full;
}

// ---------- S3 (Vultr Object Storage) ----------
let s3: S3Client | null = null;
function s3Client(): S3Client {
  if (!config.S3_ENDPOINT || !config.S3_BUCKET || !config.S3_ACCESS_KEY || !config.S3_SECRET_KEY) {
    throw new AppError(500, 'STORAGE_NOT_CONFIGURED', 'S3_ENDPOINT, S3_BUCKET, S3_ACCESS_KEY and S3_SECRET_KEY are required');
  }
  if (!s3) {
    s3 = new S3Client({
      endpoint: config.S3_ENDPOINT,
      region: config.S3_REGION,
      credentials: { accessKeyId: config.S3_ACCESS_KEY, secretAccessKey: config.S3_SECRET_KEY },
      forcePathStyle: true,
    });
  }
  return s3;
}

export async function putFile(key: string, body: Buffer, mime: string): Promise<FileRef> {
  if (config.STORAGE_DRIVER === 's3') {
    await s3Client().send(new PutObjectCommand({ Bucket: config.S3_BUCKET, Key: key, Body: body, ContentType: mime }));
    return { storage: 's3', key };
  }
  const full = localPath(key);
  await fs.mkdir(path.dirname(full), { recursive: true });
  await fs.writeFile(full, body);
  return { storage: 'local', key };
}

export async function getFile(ref: FileRef): Promise<Buffer> {
  try {
    if (ref.storage === 's3') {
      const out = await s3Client().send(new GetObjectCommand({ Bucket: config.S3_BUCKET, Key: ref.key }));
      return Buffer.from(await out.Body!.transformToByteArray());
    }
    return await fs.readFile(localPath(ref.key));
  } catch (err) {
    if (err instanceof AppError) throw err;
    console.error('File read failed:', (err as Error).message);
    throw new AppError(404, 'FILE_NOT_FOUND', 'Stored file could not be found');
  }
}

export async function deleteFile(ref: FileRef): Promise<void> {
  if (ref.storage === 's3') {
    await s3Client().send(new DeleteObjectCommand({ Bucket: config.S3_BUCKET, Key: ref.key }));
    return;
  }
  await fs.rm(localPath(ref.key), { force: true });
}
